// Monta a pagina do toldo com o ultimo estado enviado pelo ESP32.
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (ms, o) => new Date(ms).toLocaleString('pt-PT', Object.assign({ timeZone: 'Europe/Lisbon' },
    o || { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }));

const st = flow.get('toldo_estado') || null;
const visto = flow.get('toldo_visto') || 0;
const pend = flow.get('toldo_pendente') || null;
const agora = Date.now();
const online = visto && (agora - visto) < 30000;

let h = `<!doctype html><html lang="pt"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="refresh" content="10"><title>Toldo</title><style>
body{font-family:system-ui,sans-serif;margin:16px;max-width:640px;color:#222;background:#fafafa}
h1{font-size:22px;margin:0 0 12px}.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px;margin-bottom:12px}
table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:6px 4px;border-bottom:1px solid #eee;text-align:left}
th{color:#666;font-weight:600}.alerta{color:#b00020;font-weight:600}.ok{color:#1b7f3b;font-weight:600}.muted{color:#777;font-size:13px}
.botoes{display:flex;gap:8px}.botoes form{flex:1;margin:0}
button{width:100%;padding:16px 0;font-size:18px;font-weight:600;border-radius:10px;border:1px solid #bbb;background:#fff;cursor:pointer}
button:active{background:#eee}.stop{border-color:#b00020;color:#b00020}
</style></head><body><h1>Toldo</h1>
<div class="card botoes">
<form method="post" action="cmd"><input type="hidden" name="cmd" value="up"><button>&#9650; UP</button></form>
<form method="post" action="cmd"><input type="hidden" name="cmd" value="stop"><button class="stop">&#9632; STOP</button></form>
<form method="post" action="cmd"><input type="hidden" name="cmd" value="down"><button>&#9660; DOWN</button></form>
</div><div class="card">`;

if (online) h += `<div class="ok">ESP32 ligado (último contacto há ${Math.round((agora - visto) / 1000)} s)</div>`;
else if (visto) h += `<div class="alerta">ESP32 sem contacto desde ${esc(fmt(visto))}</div>`;
else h += `<div class="alerta">O ESP32 ainda não contactou o servidor.</div>`;

if (pend) h += `<div class="muted">Comando à espera do ESP32: ${esc(pend.cmd.toUpperCase())}</div>`;

if (st) {
    h += `<div><b>Estado:</b> ${esc(st.estado)}${st.desconhecido ? ' (ainda por confirmar)' : ''}</div>`;
    h += `<div><b>Modo vento:</b> ${st.emVento ? 'sim (antes estava ' + esc(st.antesVento) + ')' : 'não'}</div>`;
    if (st.falhaPrevisao) h += `<div class="alerta">Previsão em falta. Nova tentativa às ${esc(st.proxima)}</div>`;
    else h += `<div><b>Próxima verificação:</b> ${esc(st.proxima)}</div>`;
    const c = st.cfg;
    if (c) {
        h += `<div class="muted">Limites: vento &gt; ${esc(c.vento)} km/h ou rajadas &gt; ${esc(c.rajada)} km/h → UP. ` +
             `Chuva ≥ ${esc(c.chuva)} mm → DOWN.` +
             (Number(c.interv) > 0 ? ` No máximo 1 movimento automático a cada ${esc(c.interv)} min` +
              (c.vign ? ' (exceto recolher por vento)' : '') + '.' : '') + `</div>`;
    } else {
        h += `<div class="muted">Limites: vento / rajadas acima de ${esc(st.ventoMax)} km/h → UP. Chuva ≥ ${esc(st.chuvaMin)} mm → DOWN.</div>`;
    }
}
if (flow.get('toldo_cfg_pendente')) h += `<div class="muted">Alterações de configuração à espera do ESP32.</div>`;
h += `<div style="margin-top:6px"><a href="config">Configurações</a></div>`;
h += `</div><div class="card"><b>Últimas 6 horas</b><table><tr><th>Hora</th><th>Vento</th><th>Rajadas</th><th>Chuva</th><th>Ação</th></tr>`;

const hist = (st && Array.isArray(st.hist)) ? st.hist : [];
const n = v => (v === undefined || v === null) ? '-' : esc(v);
for (const r of hist) {
    h += `<tr><td>${esc(fmt(r.t * 1000))}</td><td>${n(r.v)} km/h</td><td>${n(r.r)} km/h</td><td>${n(r.c)} mm</td><td>${esc(r.a)}</td></tr>`;
}
if (!hist.length) h += `<tr><td colspan="5" class="muted">Sem registos nas últimas 6 horas.</td></tr>`;
h += `</table><div class="muted">Previsão Open-Meteo. A página atualiza a cada 10 segundos.</div></div></body></html>`;

msg.payload = h;
msg.headers = { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' };
return msg;

// Botao da pagina: guarda o comando para o ESP32 ir buscar.
const c = String((msg.payload && msg.payload.cmd) || '').toLowerCase();
if (['up', 'down', 'stop'].includes(c)) {
    flow.set('toldo_pendente', { cmd: c, quando: Date.now() });
    node.status({ fill: 'blue', shape: 'dot', text: 'pendente: ' + c });
}
msg.statusCode = 303;
msg.headers = { Location: '/', 'Cache-Control': 'no-store' };
msg.payload = '';
return msg;

// O ESP32 envia o estado e recebe o comando pendente (se houver).
const p = msg.payload;
if (p && typeof p === 'object') {
    flow.set('toldo_estado', p);
    flow.set('toldo_visto', Date.now());
}
let cmd = '';
const pend = flow.get('toldo_pendente');
if (pend) {
    if (Date.now() - pend.quando < 60000) cmd = pend.cmd;   // comandos com mais de 1 min sao descartados
    flow.set('toldo_pendente', null);
}
const resp = { cmd };
const pc = flow.get('toldo_cfg_pendente');
if (pc) {
    if (Date.now() - pc.quando < 600000) resp.cfg = pc.cfg;   // alteracoes com mais de 10 min sao descartadas
    flow.set('toldo_cfg_pendente', null);
}
node.status({ fill: 'green', shape: 'dot',
    text: 'ESP32 ' + new Date().toLocaleTimeString('pt-PT', { timeZone: 'Europe/Lisbon' }) +
          (cmd ? ' -> ' + cmd : '') + (resp.cfg ? ' -> config' : '') });
msg.payload = resp;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
return msg;

// Pagina de configuracoes: mostra os valores que o ESP32 enviou e deixa muda-los.
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = ms => new Date(ms).toLocaleTimeString('pt-PT', { timeZone: 'Europe/Lisbon', hour: '2-digit', minute: '2-digit' });
const st = flow.get('toldo_estado') || null;
const pc = flow.get('toldo_cfg_pendente') || null;
const c = st && st.cfg;
const q = (msg.req && msg.req.query) || {};

const campo = (nome, rotulo, valor, ajuda) =>
    `<label><b>${rotulo}</b><input type="number" step="any" name="${nome}" value="${esc(valor)}"></label><div class="muted">${ajuda}</div>`;

let h = `<!doctype html><html lang="pt"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Toldo: configurações</title><style>
body{font-family:system-ui,sans-serif;margin:16px;max-width:640px;color:#222;background:#fafafa}
h1{font-size:22px;margin:0 0 12px}.card{background:#fff;border:1px solid #ddd;border-radius:10px;padding:12px;margin-bottom:12px}
label{display:block;margin-top:12px}input[type=number]{display:block;width:100%;box-sizing:border-box;padding:8px;font-size:16px;margin-top:4px;border:1px solid #bbb;border-radius:8px}
.muted{color:#777;font-size:13px;margin-top:2px}.ok{color:#1b7f3b;font-weight:600}.alerta{color:#b00020;font-weight:600}
button{padding:12px 18px;font-size:16px;font-weight:600;border-radius:10px;border:1px solid #bbb;background:#fff;cursor:pointer;margin-top:16px}
.principal{background:#1b5fb3;color:#fff;border-color:#1b5fb3}
</style></head><body><h1>Configurações</h1>`;

if (q.ok === '1') h += `<div class="card ok">Enviado. O ESP32 aplica as alterações nos próximos segundos. Recarrega a página para ver os valores em uso.</div>`;
if (pc) h += `<div class="card muted">Há alterações enviadas às ${esc(fmt(pc.quando))} à espera do ESP32.</div>`;

if (!c) {
    h += `<div class="card alerta">Ainda não há configurações do ESP32. Confirma que o ESP32 tem a versão mais recente do código e que está ligado.</div>`;
} else {
    h += `<form method="post" action="config" class="card">`;
    h += campo('vento',  'Vento médio (km/h)', c.vento,  'Recolhe se o vento médio previsto for acima deste valor. Entre 5 e 100.');
    h += campo('rajada', 'Rajadas (km/h)',     c.rajada, 'Recolhe se as rajadas previstas forem acima deste valor. Entre 5 e 150.');
    h += campo('chuva',  'Chuva (mm numa hora)', c.chuva, 'Estende se a chuva prevista for igual ou acima deste valor. Entre 0 e 20.');
    h += campo('interv', 'Tempo mínimo entre movimentos (min)', c.interv,
        'A automação não mexe o toldo mais do que uma vez neste intervalo. 0 = sem limite. Entre 0 e 360.');
    h += `<label><input type="checkbox" name="vign" value="1"${c.vign ? ' checked' : ''}> <b>O vento pode recolher o toldo mesmo antes desse tempo</b></label>`;
    h += campo('stop',  'STOP depois do UP (s)', c.stop,
        'No recolher por vento: segundos até ao STOP, para ficar um bocado de fora. 0 = recolhe tudo. Entre 0 e 120.');
    h += campo('pulso', 'Duração do toque nos botões (ms)', c.pulso, 'Entre 50 e 2000.');
    if (c.nini !== undefined) {   // so aparece se o ESP32 ja tiver a versao com modo noite
        h += campo('nini', 'Modo noite: início (hora)', c.nini,
            'A partir desta hora só mexe para recolher por vento ou estender com chuva. Entre 0 e 23.');
        h += campo('nfim', 'Modo noite: fim (hora)', c.nfim,
            'Até esta hora. Igual ao início = modo noite desligado. Entre 0 e 23.');
    }
    h += campo('lat',   'Latitude',  c.lat, 'Local da previsão. Entre -90 e 90.');
    h += campo('lon',   'Longitude', c.lon, 'Local da previsão. Entre -180 e 180.');
    h += `<button class="principal">Guardar</button></form>`;
    h += `<form method="post" action="config" class="card" onsubmit="return confirm('Repor todos os valores por defeito?')">
<input type="hidden" name="reset" value="1"><div class="muted">Por defeito: vento 25, rajadas 30, chuva 0,2, 60 min entre movimentos,
vento ignora esse tempo, STOP aos 23,5 s, toque de 100 ms, noite das 20h às 7h, aeroporto de Lisboa.</div>
<button>Repor valores por defeito</button></form>`;
}
h += `<p><a href="./">← Voltar</a></p></body></html>`;

msg.payload = h;
msg.headers = { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' };
return msg;

// Guarda as alteracoes de configuracao para o ESP32 ir buscar (ele valida os valores).
const p = msg.payload || {};
let cfg;
if (p.reset) {
    cfg = { reset: true };
} else {
    cfg = { vign: p.vign === '1' };
    for (const k of ['vento', 'rajada', 'chuva', 'interv', 'stop', 'pulso', 'lat', 'lon', 'nini', 'nfim']) {
        if (p[k] !== undefined) cfg[k] = String(p[k]);
    }
}
flow.set('toldo_cfg_pendente', { cfg, quando: Date.now() });
node.status({ fill: 'blue', shape: 'dot', text: 'config pendente' });
msg.statusCode = 303;
msg.headers = { Location: '/config?ok=1', 'Cache-Control': 'no-store' };
msg.payload = '';
return msg;
